<template>
  <AdminLayout>
    <main class="mx-auto max-w-7xl space-y-6" aria-labelledby="treasury-payments-title">
      <AdminPageHeader eyebrow="TESORERÍA" title="Validación de pagos" title-id="treasury-payments-title" description="Revisa y confirma presentaciones de transferencia.">
        <template #action><button type="button" class="rounded-lg border border-white/30 px-4 py-2 text-sm font-bold" :disabled="listLoading" @click="load()"><i class="pi pi-refresh mr-2" :class="{ 'pi-spin': listLoading }" aria-hidden="true" />Actualizar</button></template>
      </AdminPageHeader>
      <form class="grid gap-4 rounded-2xl bg-white p-4 shadow-sm sm:grid-cols-2 lg:grid-cols-4" @submit.prevent="apply">
        <label class="text-sm font-bold text-slate-700">Buscar<input v-model.trim="filters.search" class="field mt-1 h-10" placeholder="Pedido u operación" /></label>
        <label class="text-sm font-bold text-slate-700">Estado<select v-model="filters.status" class="field mt-1 h-10"><option value="">Todos</option><option v-for="value in statuses" :key="value" :value="value">{{ statusLabel(value) }}</option></select></label>
        <label class="text-sm font-bold text-slate-700">Canal<select v-model="filters.channel" class="field mt-1 h-10"><option value="">Todos</option><option v-for="value in channels" :key="value" :value="value">{{ channelLabel(value) }}</option></select></label>
        <div class="flex items-end gap-2"><button type="submit" class="h-10 rounded-lg bg-blue-700 px-4 text-sm font-bold text-white" :disabled="listLoading">Aplicar</button><button type="button" class="h-10 rounded-lg border px-4 text-sm font-bold" :disabled="listLoading" @click="clear">Limpiar</button></div>
      </form>
      <section v-if="listError" class="rounded-xl border border-red-200 bg-red-50 p-4 text-red-900" role="alert">{{ listError }} <button type="button" class="ml-2 font-bold underline" @click="load()">Reintentar</button></section>
      <section class="overflow-hidden rounded-2xl bg-white shadow-sm">
        <div v-if="listLoading" class="space-y-3 p-3"><div v-for="n in 4" :key="n" class="h-20 animate-pulse rounded-xl bg-slate-100" /></div>
        <template v-else-if="rows.length">
          <div class="space-y-3 p-3 md:hidden"><article v-for="row in rows" :key="row.id" class="rounded-xl border border-slate-200 p-4"><div class="flex items-start justify-between gap-3"><div><p class="font-black">{{ row.order_number }}</p><p class="text-sm text-slate-600">{{ row.customer?.name || '—' }}</p></div><AdminStatusBadge :active="row.status === 'pending_review'" :active-label="statusLabel(row.status)" :inactive-label="statusLabel(row.status)" /></div><p v-if="manualReview(row)" class="mt-2 rounded bg-amber-50 px-2 py-1 text-xs font-bold text-amber-900">Reserva no vigente · Revisión manual requerida</p><dl class="mt-3 grid grid-cols-2 gap-3 text-sm"><div><dt class="text-slate-500">Canal</dt><dd>{{ channelLabel(row.channel) }}</dd></div><div><dt class="text-slate-500">Importe</dt><dd>{{ money(row.expected_amount, row.currency) }}</dd></div><div><dt class="text-slate-500">Operación</dt><dd class="font-mono">{{ row.operation_number_masked }}</dd></div><div><dt class="text-slate-500">Presentado</dt><dd>{{ date(row.submitted_at) }}</dd></div></dl><div class="mt-4 flex justify-end"><AdminIconButton icon="pi pi-eye" :label="`Ver ${row.order_number}`" @click="openDetail(row)" /></div></article></div>
          <div class="hidden overflow-x-auto md:block"><table class="min-w-[1050px] w-full text-left text-sm"><thead class="bg-slate-100 text-xs uppercase text-slate-600"><tr><th v-for="heading in headings" :key="heading" scope="col" class="p-4">{{ heading }}</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id" class="border-t border-slate-100"><td class="p-4 font-bold">{{ row.order_number }}</td><td class="p-4"><p>{{ row.customer?.name || '—' }}</p><small class="text-slate-500">{{ row.customer?.email || '' }}</small></td><td class="p-4">{{ channelLabel(row.channel) }}</td><td class="p-4">{{ money(row.expected_amount, row.currency) }}</td><td class="p-4 font-mono">{{ row.operation_number_masked }}</td><td class="p-4">{{ row.receiving_account?.display_name || '—' }}</td><td class="p-4"><AdminStatusBadge :active="row.status === 'pending_review'" :active-label="statusLabel(row.status)" :inactive-label="statusLabel(row.status)" /><p v-if="manualReview(row)" class="mt-1 text-xs font-bold text-amber-800">Revisión manual requerida</p></td><td class="p-4">{{ date(row.declared_paid_at) }}</td><td class="p-4">{{ date(row.submitted_at) }}</td><td class="p-4">{{ row.pending_minutes == null ? '—' : `${row.pending_minutes} min` }}</td><td class="p-4"><AdminIconButton icon="pi pi-eye" :label="`Ver ${row.order_number}`" @click="openDetail(row)" /></td></tr></tbody></table></div>
        </template>
        <AdminEmptyState v-else icon="pi pi-wallet" title="No hay presentaciones" description="No se encontraron presentaciones con los filtros actuales." />
      </section>
      <AdminPagination :page="meta.current_page || 1" :last-page="meta.last_page || 1" :summary="summary" :loading="listLoading" @change="load" />

      <div v-if="detail" class="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/60 p-3" role="dialog" aria-modal="true" aria-labelledby="treasury-detail-title" @mousedown.self="!busy && closeDetail()">
        <section class="flex max-h-[94vh] w-full max-w-3xl flex-col overflow-hidden rounded-2xl bg-white shadow-2xl"><header class="flex items-start justify-between border-b p-5"><div><h2 id="treasury-detail-title" class="text-xl font-black">Presentación {{ detail.order_number }}</h2><p class="mt-1 text-sm text-slate-600">Detalle para validación de Tesorería.</p></div><AdminIconButton icon="pi pi-times" label="Cerrar detalle" :disabled="busy" @click="closeDetail" /></header><div class="min-h-0 flex-1 space-y-5 overflow-y-auto p-5"><p v-if="detailError" class="rounded bg-red-50 p-3 text-red-900" role="alert">{{ detailError }}</p><template v-else><div class="grid gap-3 sm:grid-cols-2"><div v-for="item in detailItems" :key="item.label" class="rounded-lg bg-slate-50 p-3"><p class="text-xs font-bold uppercase text-slate-500">{{ item.label }}</p><p class="mt-1 break-words text-sm font-medium">{{ item.value }}</p></div></div><article v-if="manualReview(detail)" class="rounded-xl border border-amber-300 bg-amber-50 p-4 text-amber-950"><h3 class="font-bold">Reserva no vigente</h3><p class="mt-1 text-sm">Este pago requiere revisión manual. No se debe aprobar ni reasignar stock automáticamente.</p><p class="mt-2 text-sm font-bold">Revisión manual requerida</p></article><article v-if="detail.status === 'approved'" class="rounded-xl border border-emerald-300 bg-emerald-50 p-4 text-emerald-950"><h3 class="font-bold">Pago aprobado</h3><dl class="mt-3 grid gap-2 text-sm sm:grid-cols-2"><div><dt class="text-slate-600">Transacción</dt><dd>{{ detail.approved_payment?.id || '—' }}</dd></div><div><dt class="text-slate-600">Estado</dt><dd>{{ detail.approved_payment?.status || 'approved' }}</dd></div><div><dt class="text-slate-600">Confirmado</dt><dd>{{ date(detail.approved_payment?.confirmed_at) }}</dd></div><div><dt class="text-slate-600">Actor Treasury</dt><dd>{{ detail.approved_payment?.confirmer?.name || '—' }}</dd></div><div><dt class="text-slate-600">Reserva</dt><dd>Consumida</dd></div></dl></article><article v-if="detail.status === 'observed' || detail.status === 'rejected'" class="rounded-xl border p-4"><h3 class="font-bold">Revisión</h3><dl class="mt-3 grid gap-2 text-sm sm:grid-cols-2"><div><dt class="text-slate-500">Estado</dt><dd>{{ statusLabel(detail.status) }}</dd></div><div v-if="detail.review?.reviewed_at"><dt class="text-slate-500">Fecha</dt><dd>{{ date(detail.review.reviewed_at) }}</dd></div><div v-if="detail.review?.reviewer"><dt class="text-slate-500">Revisor</dt><dd>{{ detail.review.reviewer.name || '—' }}</dd></div><div v-if="detail.review?.reason" class="sm:col-span-2"><dt class="text-slate-500">Motivo</dt><dd>{{ detail.review.reason }}</dd></div></dl></article><section><h3 class="font-black">Historial</h3><p v-if="historyError" class="mt-2 text-sm text-red-800" role="alert">{{ historyError }} <button type="button" class="font-bold underline" @click="loadHistory">Reintentar</button></p><p v-else-if="historyLoading" class="mt-2 text-sm text-slate-500">Cargando historial…</p><ol v-else class="mt-3 space-y-3 border-l border-slate-200 pl-4"><li v-for="event in history" :key="`${event.event}-${event.occurred_at}`" class="relative"><span class="absolute -left-[21px] top-1 h-3 w-3 rounded-full bg-blue-600" /><p class="font-bold">{{ eventLabel(event.event) }} <span v-if="event.from_status">· {{ statusLabel(event.from_status) }} → {{ statusLabel(event.to_status) }}</span></p><p v-if="event.actor?.name" class="text-sm text-slate-600">{{ event.actor.name }}</p><p v-if="event.reason" class="text-sm text-slate-700">{{ event.reason }}</p><p class="text-xs text-slate-500">{{ date(event.occurred_at) }}</p></li></ol></section></template></div><footer class="flex flex-wrap justify-end gap-3 border-t p-5"><button type="button" class="rounded-lg border px-4 py-2 font-bold" :disabled="busy" @click="closeDetail">Cerrar</button><button v-if="canObserve" type="button" class="rounded-lg border border-amber-400 px-4 py-2 font-bold text-amber-800" :disabled="busy" @click="openDecision('observe')">Marcar como observado</button><button v-if="canReject" type="button" class="rounded-lg bg-red-700 px-4 py-2 font-bold text-white" :disabled="busy" @click="openDecision('reject')">Rechazar</button><button v-if="canApprove" type="button" class="rounded-lg bg-emerald-700 px-4 py-2 font-bold text-white shadow-sm hover:bg-emerald-800" :disabled="busy" @click="openApprovalConfirmation">Aprobar pago</button></footer></section>
      </div>
      <div v-if="decisionMode" class="fixed inset-0 z-[60] flex items-center justify-center bg-slate-950/60 p-3" role="dialog" aria-modal="true" aria-labelledby="decision-title"><form class="w-full max-w-lg rounded-2xl bg-white p-5 shadow-2xl" @submit.prevent="decide"><h2 id="decision-title" class="text-xl font-black">{{ decisionMode === 'reject' ? 'Rechazar presentación' : 'Marcar como observado' }}</h2><label class="mt-4 block text-sm font-bold">Motivo<textarea v-model.trim="reason" class="field mt-1" rows="4" required maxlength="1000"></textarea></label><p v-if="fieldErrors.reason" class="mt-1 text-sm text-red-700">{{ fieldErrors.reason[0] }}</p><p v-if="decisionError" class="mt-2 text-sm text-red-700" role="alert">{{ decisionError }}</p><footer class="mt-5 flex justify-end gap-3"><button type="button" class="rounded-lg border px-4 py-2" :disabled="decisionLoading" @click="closeDecision">Cancelar</button><button type="submit" class="rounded-lg bg-blue-700 px-4 py-2 font-bold text-white" :disabled="decisionLoading">{{ decisionLoading ? 'Procesando…' : 'Confirmar' }}</button></footer></form></div>
      <div v-if="approvalConfirmOpen" class="fixed inset-0 z-[60] flex items-center justify-center bg-slate-950/60 p-3" role="dialog" aria-modal="true" aria-labelledby="approval-confirmation-title" @mousedown.self="!approvalLoading && closeApprovalConfirmation()"><section class="flex max-h-[94vh] w-full max-w-xl flex-col overflow-hidden rounded-2xl bg-white shadow-2xl"><header class="flex items-start justify-between border-b p-5"><div><h2 id="approval-confirmation-title" class="text-xl font-black">Confirmar aprobación de pago</h2><p class="mt-1 text-sm text-slate-600">Verifica la presentación antes de confirmar.</p></div><AdminIconButton icon="pi pi-times" label="Cerrar confirmación de aprobación" :disabled="approvalLoading" @click="closeApprovalConfirmation" /></header><div class="min-h-0 flex-1 space-y-4 overflow-y-auto p-5"><dl class="grid gap-3 text-sm sm:grid-cols-2"><div><dt class="text-slate-500">Pedido</dt><dd class="font-bold">{{ detail?.order_number }}</dd></div><div><dt class="text-slate-500">Cliente</dt><dd>{{ detail?.customer?.name || '—' }}</dd></div><div><dt class="text-slate-500">Canal</dt><dd>{{ channelLabel(detail?.channel) }}</dd></div><div><dt class="text-slate-500">Importe</dt><dd>{{ money(detail?.expected_amount, detail?.currency) }}</dd></div><div><dt class="text-slate-500">Operación</dt><dd class="font-mono">{{ detail?.operation_number || detail?.operation_number_masked || '—' }}</dd></div><div><dt class="text-slate-500">Cuenta receptora</dt><dd>{{ detail?.receiving_account?.display_name || '—' }}</dd></div><div class="sm:col-span-2"><dt class="text-slate-500">Reserva</dt><dd>{{ reservationLabel(detail?.reservation_status) }}</dd></div></dl><p class="rounded-xl border border-amber-300 bg-amber-50 p-4 text-sm font-medium text-amber-950">Esta acción confirmará el pago y consumirá la reserva de inventario. No podrá repetirse ni deshacerse desde esta pantalla.</p><p v-if="approvalError" class="rounded bg-red-50 p-3 text-sm text-red-900" role="alert">{{ approvalError }}</p></div><footer class="flex flex-col-reverse gap-3 border-t p-5 sm:flex-row sm:justify-end"><button type="button" class="rounded-lg border px-4 py-2 font-bold" :disabled="approvalLoading" @click="closeApprovalConfirmation">Cancelar</button><button type="button" class="rounded-lg bg-emerald-700 px-4 py-2 font-bold text-white disabled:opacity-50" :disabled="approvalLoading" @click="approvePayment">{{ approvalLoading ? 'Aprobando…' : 'Confirmar aprobación' }}</button></footer></section></div>
    </main>
  </AdminLayout>
</template>

<script setup>
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { useToast } from 'primevue/usetoast'
import AdminLayout from '@/layouts/AdminLayout.vue'
import AdminPageHeader from '@/components/admin/AdminPageHeader.vue'
import AdminStatusBadge from '@/components/admin/AdminStatusBadge.vue'
import AdminIconButton from '@/components/admin/AdminIconButton.vue'
import AdminEmptyState from '@/components/admin/AdminEmptyState.vue'
import AdminPagination from '@/components/admin/AdminPagination.vue'
import api from '@/api'

const toast = useToast(); const rows = ref([]); const meta = ref({}); const detail = ref(null); const history = ref([])
const listLoading = ref(false); const listError = ref(''); const detailError = ref(''); const historyLoading = ref(false); const historyError = ref('')
const decisionMode = ref(''); const decisionLoading = ref(false); const decisionError = ref(''); const reason = ref(''); const fieldErrors = ref({})
const approvalConfirmOpen = ref(false); const approvalLoading = ref(false); const approvalError = ref(''); const approvalBlocked = ref(false)
const filters = reactive({ search: '', status: '', channel: '', date_from: '', date_to: '', per_page: 20 }); let controller = null; let requestId = 0; let detailRequestId = 0
const statuses = ['pending_review', 'observed', 'approved', 'rejected', 'expired', 'canceled']; const channels = ['yape', 'plin', 'bank_transfer']; const headings = ['Pedido', 'Cliente', 'Canal', 'Importe', 'Operación', 'Cuenta receptora', 'Estado', 'Fecha declarada', 'Presentado', 'Tiempo pendiente', 'Acciones']
const busy = computed(() => decisionLoading.value || approvalLoading.value); const summary = computed(() => meta.value.total ? `Mostrando ${meta.value.from}–${meta.value.to} de ${meta.value.total}` : 'Sin registros'); const manualReview = row => ['pending_review', 'observed'].includes(row?.status) && row?.reservation_status !== 'active'; const canApprove = computed(() => detail.value?.status === 'pending_review' && detail.value?.reservation_status === 'active' && !approvalBlocked.value); const canObserve = computed(() => ['pending_review', 'observed'].includes(detail.value?.status) && !manualReview(detail.value) && !approvalBlocked.value); const canReject = computed(() => ['pending_review', 'observed'].includes(detail.value?.status) && !approvalBlocked.value)
const detailItems = computed(() => detail.value ? [{ label: 'Cliente', value: detail.value.customer?.name || '—' }, { label: 'Correo', value: detail.value.customer?.email || '—' }, { label: 'Canal', value: channelLabel(detail.value.channel) }, { label: 'Importe', value: money(detail.value.expected_amount, detail.value.currency) }, { label: 'Operación', value: detail.value.operation_number || '—' }, { label: 'Cuenta receptora', value: detail.value.receiving_account?.display_name || '—' }, { label: 'Fecha declarada', value: date(detail.value.declared_paid_at) }, { label: 'Fecha presentada', value: date(detail.value.submitted_at) }, { label: 'Estado', value: statusLabel(detail.value.status) }, { label: 'Reserva', value: reservationLabel(detail.value.reservation_status) }] : [])
const statusLabel = value => ({ pending_review: 'Pendiente', observed: 'Observada', approved: 'Aprobada', rejected: 'Rechazada', expired: 'Vencida', canceled: 'Cancelada' })[value] || value; const reservationLabel = value => ({ active: 'Activa', expired: 'Reserva vencida', released: 'Reserva liberada', consumed: 'Reserva consumida', none: 'Sin reserva' })[value] || '—'; const eventLabel = value => ({ submitted: 'Presentado', observed: 'Observado', corrected: 'Corregido y reenviado', rejected: 'Rechazado', approved: 'Aprobado' })[value] || value; const channelLabel = value => ({ yape: 'Yape', plin: 'Plin', bank_transfer: 'Transferencia bancaria' })[value] || value; const money = (value, currency = 'PEN') => Number.isFinite(Number(value)) ? new Intl.NumberFormat('es-PE', { style: 'currency', currency }).format(Number(value)) : '—'; const date = value => value ? new Intl.DateTimeFormat('es-PE', { dateStyle: 'short', timeStyle: 'short', timeZone: 'America/Lima' }).format(new Date(value)) : '—'; const message = error => error.response?.data?.message || Object.values(error.response?.data?.errors || {})[0]?.[0] || 'No se pudo completar la operación.'
function params(page) { return Object.fromEntries(Object.entries({ ...filters, page }).filter(([, value]) => value !== '' && value != null)) }
async function load(page = meta.value.current_page || 1) { controller?.abort(); controller = new AbortController(); const id = ++requestId; listLoading.value = true; listError.value = ''; try { const { data } = await api.get('/treasury/payment-submissions', { params: params(page), signal: controller.signal }); if (id === requestId) { rows.value = data.data || []; meta.value = data } } catch (error) { if (error.code !== 'ERR_CANCELED' && id === requestId) listError.value = message(error) } finally { if (id === requestId) listLoading.value = false } }
function apply() { load(1) } function clear() { Object.assign(filters, { search: '', status: '', channel: '', date_from: '', date_to: '', per_page: 20 }); load(1) }
async function refreshDetail() { if (!detail.value) return null; const id = ++detailRequestId; detailError.value = ''; try { const { data } = await api.get(`/treasury/payment-submissions/${detail.value.id}`); if (id === detailRequestId) detail.value = data.data; return detail.value } catch (error) { if (id === detailRequestId) detailError.value = message(error); return null } }
async function openDetail(row) { detail.value = row; history.value = []; historyError.value = ''; approvalBlocked.value = false; if (await refreshDetail()) await loadHistory() } function closeDetail() { if (!busy.value) { detail.value = null; history.value = []; detailError.value = ''; historyError.value = ''; approvalConfirmOpen.value = false; approvalBlocked.value = false } }
async function loadHistory() { if (!detail.value) return; historyLoading.value = true; historyError.value = ''; try { history.value = (await api.get(`/treasury/payment-submissions/${detail.value.id}/history`)).data.data || [] } catch (error) { historyError.value = message(error) } finally { historyLoading.value = false } }
function openDecision(mode) { decisionMode.value = mode; reason.value = ''; decisionError.value = ''; fieldErrors.value = {} } function closeDecision() { if (!decisionLoading.value) decisionMode.value = '' }
async function decide() { if (decisionLoading.value || !detail.value) return; decisionLoading.value = true; decisionError.value = ''; fieldErrors.value = {}; try { await api.patch(`/treasury/payment-submissions/${detail.value.id}/${decisionMode.value}`, { reason: reason.value }); decisionMode.value = ''; await refreshDetail(); await load(meta.value.current_page); await loadHistory(); toast.add({ severity: 'success', summary: 'Actualizado', life: 3500 }) } catch (error) { fieldErrors.value = error.response?.data?.errors || {}; decisionError.value = message(error); toast.add({ severity: 'error', summary: 'No se pudo actualizar', detail: decisionError.value, life: 4000 }) } finally { decisionLoading.value = false } }
function openApprovalConfirmation() { if (canApprove.value) { approvalError.value = ''; approvalConfirmOpen.value = true } } function closeApprovalConfirmation() { if (!approvalLoading.value) { approvalConfirmOpen.value = false; approvalError.value = '' } } async function reloadAfterApproval() { await refreshDetail(); await loadHistory(); await load(meta.value.current_page) }
async function approvePayment() { if (approvalLoading.value || !canApprove.value || !detail.value) return; approvalLoading.value = true; approvalError.value = ''; try { await api.patch(`/treasury/payment-submissions/${detail.value.id}/approve`, {}); approvalConfirmOpen.value = false; await reloadAfterApproval(); toast.add({ severity: 'success', summary: 'Pago aprobado correctamente', life: 3500 }) } catch (error) { const code = error.response?.data?.code; if (error.response?.status === 409) { approvalConfirmOpen.value = false; approvalBlocked.value = true; await reloadAfterApproval(); if (code === 'payment_submission_approval_conflict' && detail.value?.status === 'approved') toast.add({ severity: 'success', summary: 'Pago aprobado correctamente', detail: 'Se recuperó la aprobación ya registrada.', life: 4000 }); else toast.add({ severity: 'warn', summary: code === 'manual_resolution_required' ? 'Revisión manual requerida' : 'Conflicto de aprobación', detail: message(error), life: 5000 }); return } approvalError.value = message(error); toast.add({ severity: 'error', summary: 'No se pudo aprobar el pago', detail: approvalError.value, life: 5000 }) } finally { approvalLoading.value = false } }
onMounted(() => load()); onBeforeUnmount(() => controller?.abort())
</script>
